const text=(p,name,content,size=14,color="#18181B",weight="normal")=>Insert(p,{type:"text",name,content,fontFamily:"Inter",fontSize:size,fontWeight:weight,fill:color,textGrowth:"fixed-width",width:"fill_container",lineHeight:1.45});
for(const [device,width,height,y,pad,mainWidth] of [["desktop1440",1440,1000,1100,64,640],["mobile390",390,1040,2300,20,350]]){
const screen=Insert(document,{type:"frame",name:"A · "+device+" · Edit",x:1600,y,width,height,layout:"vertical",padding:pad,gap:32,alignItems:"center",fill:"#FAFAFA",clip:true,placeholder:true,metadata:{type:"screen",state:"draft",device,synthetic:true}});
const nav=Insert(screen,{type:"frame",name:"Account navigation",width:"fill_container",layout:"horizontal",gap:16,alignItems:"center",padding:[0,0,16,0],stroke:"#E4E4E7",strokeWidth:{bottom:1}});
text(nav,"Breadcrumb","Account / Notifications",14,"#52525B");
const main=Insert(screen,{type:"frame",name:"Settings content",layout:"vertical",width:mainWidth,gap:24});
const heading=Insert(main,{type:"frame",name:"Page heading",layout:"vertical",width:"fill_container",gap:8});
text(heading,"Title","Notification settings",device==="desktop1440"?32:28,"#18181B","600");
text(heading,"Description","Choose when you hear from us.",16,"#52525B");
const summary=Insert(main,{type:"ref",ref:"CR7qO",name:"Connected saved summary",width:"fill_container",descendants:{"yu3h0":{content:"Currently saved · Daily",fontWeight:"500"},"JmSWy":{content:"Notifications on · alex@example.test",textGrowth:"fixed-width",width:"fill_container"}}});
const card=Insert(main,{type:"ref",ref:"q5njV2",name:"Connected settings card",width:"fill_container"});
const action=Insert(main,{type:"frame",name:"Review actions",layout:"vertical",width:"fill_container",gap:12});
text(action,"Draft status","Unsaved change: Daily → Weekly",13,"#52525B");
const button=Insert(action,{type:"frame",name:"Review changes button",layout:"horizontal",width:device==="desktop1440"?"fit_content":"fill_container",padding:[12,20],alignItems:"center",justifyContent:"center",fill:"#18181B",cornerRadius:6,metadata:{type:"action",action:"open-confirmation"}});
Insert(button,{type:"text",name:"Review changes label",content:"Review changes",fontFamily:"Inter",fontSize:14,fontWeight:"500",fill:"#FFFFFF"});
text(main,"Prototype note","Local prototype · Synthetic data. No email is sent.",12,"#71717A");
Update(screen,{placeholder:false});
Print({device,screen,main,summary,card,action,button});
}
